wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock once for this run.
        let now = wall_clock::now();

        // One permitted fetch. A transport failure is a value, not a trap:
        // it reports zero characters rather than failing the node.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!(
            "heartbeat at {} fetched {} chars from {}",
            now.seconds, fetched, feed_url
        );
        let accepted = notifier::notify(&message);

        // The contract is `notified == true`. If the channel refuses the
        // message, do not produce an output that violates the ensures:
        // trap instead (panic = "abort" makes this a wasm trap).
        assert!(accepted, "digest notifier refused the heartbeat notification");

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified: accepted,
        }
    }
}

export!(Node);
